# Generated by OrchestKit Claude Plugin
# Created: 2026-07-31

"""Whether a loaded use case is any good (plan T2.2, T2.7).

`catalog.py` refuses a file whose shape is wrong. This decides whether the thing it loaded
would actually measure anything, and it answers for the whole catalog at once — 27 use cases
reported together, because fixing them one failing run at a time is how a catalog ends up half
written.

Every check here exists because its absence is silent. A use case that names a tool nobody
registers, points at a person who is not in the fixture, or spells a kind the grader does not
implement still *loads*, still appears in the coverage map and still costs its dollar per run;
it simply grades nothing. That is the same defect class the Checkpoint review found four of in
the Stage-1 harness, and it is cheaper to catch here than in a $5 pass.

Returns problems rather than raising: the caller is a test, and the useful output is the list.
"""

from __future__ import annotations

import re
from typing import Any

from harness.docker_util import ProbeError

from .assertion_kinds import KINDS, MANY_SUBJECTS, ONE_SUBJECT, missing_parameters, wrong_shapes
from .assertion_kinds import A as GRADE_A
from .assertion_kinds import unknown_parameters as unknown_kind_parameters
from .catalog import EVERYTHING, UseCase
from .checks_record import ALTERNATE_KEYS
from .leak_lint import leaks, stale, unwaived
from .subjects import NEW, Tree, resolve_all

PLACEHOLDER = re.compile(r"\{([a-z_]+)\}")
# `I0000`, `F0021`, `S0003`: a Gramps id written into a use case is the defect T2.2 exists to
# remove. It is not a property of the person — regrow the fixture, insert one subject in the
# middle, import a file that renumbers a collision, and the literal now points at somebody
# else while every assertion stays green.
HARDCODED_ID = re.compile(r"\b[IFSNCEPRM]\d{4}\b")


def problems(use_cases: dict[str, UseCase], tools: set[str], tree: Tree) -> list[str]:
    """Everything wrong with the catalog, one line each."""
    found: list[str] = []
    seen_assertions: dict[str, str] = {}
    for use_case in use_cases.values():
        found += _tools(use_case, tools)
        found += _subjects(use_case, tree)
        found += _assertions(use_case, seen_assertions)
        found += _guards(use_case)
        found += _leaks(use_case, tools)
        found += _placeholders(use_case)
        found += _unused_subjects(use_case)
        found += _hardcoded_ids(use_case)
    return found


def _placeholders(use_case: UseCase) -> list[str]:
    """`{target}` in a prompt is filled with that subject's id at run time (uc26 asks for a
    record *by* id, which is the one prompt that has to carry one)."""
    return [
        f"{use_case.id}: the prompt fills in {{{name}}}, which is not a declared subject"
        for name in sorted(set(PLACEHOLDER.findall(use_case.prompt)) - set(use_case.subjects))
    ]


def _named_in_prompt(use_case: UseCase) -> set[str]:
    """Subjects the prompt spells out — "Frauke Ivarsgard" is how the model finds her.

    Such a subject earns its place by proving the fixture holds that person exactly once,
    which is the difference between a use case and an unanswerable question."""
    named = set()
    for name, selector in use_case.subjects.items():
        values = [value for key, value in selector.items() if key != "namespace"]
        if values and all(isinstance(v, str) and v in use_case.prompt for v in values):
            named.add(name)
    return named


def _unused_subjects(use_case: UseCase) -> list[str]:
    """A subject nobody asserts on, guards or names in the prompt resolves for decoration."""
    used = set(PLACEHOLDER.findall(use_case.prompt)) | _named_in_prompt(use_case)
    if use_case.guards != EVERYTHING:
        used |= {name for allowed in use_case.guards.values() for name in allowed}
    for assertion in use_case.assertions:
        for key, value in assertion.params.items():
            if key in ONE_SUBJECT and value is not None:
                used.add(str(value))
            elif key in MANY_SUBJECTS:
                used |= {str(name) for name in value or []}
    return [
        f"{use_case.id}: subject {name!r} is declared and never used"
        for name in sorted(set(use_case.subjects) - used)
    ]


def _hardcoded_ids(use_case: UseCase) -> list[str]:
    """No Gramps id anywhere in the file — prompt, selector or assertion."""
    written = sorted(set(HARDCODED_ID.findall(use_case.path.read_text(encoding="utf-8"))))
    if not written:
        return []
    return [
        f"{use_case.id}: writes the gramps ids {written} — subjects are selected from the tree, "
        "never named by id, or the file silently points at whoever holds that id next"
    ]


def _tools(use_case: UseCase, tools: set[str]) -> list[str]:
    found = []
    for role in ("primary", "decoys", "secondary"):
        for tool in getattr(use_case, role):
            if tool not in tools:
                found.append(f"{use_case.id}: {role} names {tool}, which is not registered")
    both = set(use_case.primary) & set(use_case.decoys)
    if both:
        found.append(
            f"{use_case.id}: {sorted(both)} is primary and decoy at once — the use case would "
            "assert that the tool it tests was not the route"
        )
    return found


def _subjects(use_case: UseCase, tree: Tree) -> list[str]:
    """Every subject resolves against the committed fixture, to exactly one object."""
    try:
        resolve_all(use_case.subjects, tree)
    except ProbeError as failure:
        return [f"{use_case.id}: {failure}"]
    return []


def _assertions(use_case: UseCase, seen: dict[str, str]) -> list[str]:
    found: list[str] = []
    declared = set(use_case.subjects)
    for assertion in use_case.assertions:
        if not assertion.id.startswith(f"{use_case.id}/"):
            found.append(f"{use_case.id}: assertion id {assertion.id!r} is not prefixed with it")
        if assertion.id in seen:
            found.append(
                f"{use_case.id}: assertion id {assertion.id!r} is also used by "
                f"{seen[assertion.id]} — gate 3 dedups on it, so it has to be unique"
            )
        seen[assertion.id] = use_case.id

        if assertion.kind not in KINDS:
            found.append(
                f"{use_case.id}: {assertion.id} names kind {assertion.kind!r}, which no grader "
                f"implements — known kinds are {sorted(KINDS)}"
            )
            continue
        given = set(assertion.params)
        missing = missing_parameters(assertion.kind, given)
        unknown = unknown_kind_parameters(assertion.kind, given)
        if missing:
            found.append(f"{use_case.id}: {assertion.id} is missing {sorted(missing)}")
        if unknown:
            found.append(f"{use_case.id}: {assertion.id} passes {sorted(unknown)}, unknown here")
        found += [
            f"{use_case.id}: {assertion.id} {problem}"
            for problem in wrong_shapes(assertion.kind, assertion.params)
        ]
        found += _references(use_case, assertion.id, assertion.params, declared)
        found += _contains(use_case, assertion)

    gating = any(a.kind in KINDS and KINDS[a.kind].grade == GRADE_A for a in use_case.assertions)
    if use_case.gates and not gating:
        found.append(
            f"{use_case.id}: tier {use_case.tier} may fail the run but carries no class-A "
            "assertion — only the tree may gate, never the tool log"
        )
    return found


def _references(use_case: UseCase, where: str, params: dict[str, Any], declared: set[str]) -> list:
    """Every subject an assertion names is one the use case declared, or one it creates."""
    found = []
    for key, value in params.items():
        if key in ONE_SUBJECT:
            names = [value] if value is not None else []
        elif key in MANY_SUBJECTS:
            names = list(value or [])
        else:
            continue
        for name in names:
            if not str(name).startswith(NEW) and name not in declared:
                found.append(f"{use_case.id}: {where} points at undeclared subject {name!r}")
    return found


def _contains(use_case: UseCase, assertion: Any) -> list[str]:
    """The inner shape of `alternates: contains:`, which nothing used to check.

    It cost a live run to learn that: a misspelt key inside one of those entries loaded, passed
    every check here, and then died with a `KeyError` in the middle of the sweep — after the
    model run it was grading had already been paid for.
    """
    if assertion.kind != "alternates":
        return []  # `backup_file`'s `contains:` is a string, not a list of pairs
    found = []
    for entry in assertion.params.get("contains") or []:
        if not isinstance(entry, dict) or not entry:
            found.append(f"{use_case.id}: {assertion.id} has a `contains` entry naming nothing")
            continue
        unknown = sorted(set(entry) - ALTERNATE_KEYS)
        if unknown:
            found.append(
                f"{use_case.id}: {assertion.id} matches an alternate on {unknown}, which an "
                f"alternate name does not have — it has {sorted(ALTERNATE_KEYS)}"
            )
    return found


def _guards(use_case: UseCase) -> list[str]:
    """G2-G4 name the subjects this use case is allowed to move, and nothing else."""
    if use_case.guards == EVERYTHING or use_case.maxdrop == EVERYTHING:
        if use_case.guards != use_case.maxdrop:
            return [
                f"{use_case.id}: guards and maxdrop disagree about being the wipe "
                f"({use_case.guards!r} / {use_case.maxdrop!r})"
            ]
        return []
    return [
        f"{use_case.id}: guards[{namespace}] names undeclared subject {name!r}"
        for namespace, allowed in use_case.guards.items()
        for name in allowed
        if name not in use_case.subjects
    ]


def _leaks(use_case: UseCase, tools: set[str]) -> list[str]:
    """The prompt does not name the tool it expects (T2.7)."""
    found = []
    waived = {waiver.token for waiver in use_case.waivers}
    detected = leaks(use_case.prompt, tools, use_case.primary)
    for leak in unwaived(detected, waived):
        found.append(
            f"{use_case.id}: the prompt says {leak.token!r}, a word only {leak.tool} has in its "
            "name — the model would not need the docstring to find it"
        )
    for token in sorted(stale(detected, waived)):
        found.append(
            f"{use_case.id}: waives {token!r}, which the prompt no longer contains — a waiver "
            "left behind re-arms the leak silently"
        )
    return found
